'use strict';

// Case 1: exported, never imported by the app, but called at module init.
function warmCache() {
  cache.ready = true;
  return cache;
}

// Case 2: exported, never imported by the app, but called by greet/slugify.
function normalize(s) {
  return String(s).trim().toLowerCase();
}

// Case 3: exported only inside a conditional (always true at runtime).
function debugDump(obj) {
  return JSON.stringify(obj);
}

// Case 4: one local function exported under two names; app imports only `kebab`.
function slugify(s) {
  return normalize(s).replace(/\s+/g, '-');
}

// The only export the app imports directly (besides the `kebab` alias).
function greet(name) {
  if (!cache.ready) throw new Error('cache not warmed');
  return 'hello, ' + normalize(name);
}

const cache = { ready: false };
warmCache();

exports.greet = greet;
exports.warmCache = warmCache;
exports.normalize = normalize;
exports.slugify = slugify;
exports.kebab = slugify;
if (typeof JSON.stringify === 'function') {
  exports.debugDump = debugDump;
}
